func:
// Decode the FC3 holding-register block (addr 0..8) from the simulated SunSpec
// inverter into a normalized reading. Scale factors mirror edge/sim register map.
const r = msg.payload;
if (!Array.isArray(r) || r.length < 9) { node.warn('short modbus read'); return null; }
const s16 = (v) => (v > 32767 ? v - 65536 : v);
const grid_kw = s16(r[0]) / 100;   // + import / - export at grid coupling
const pv_kw   = s16(r[1]) / 100;
const load_kw = s16(r[2]) / 100;
const batt_kw = s16(r[3]) / 100;   // + charge / - discharge
const soc_pct = r[4] / 10;
const wmax_lim_pct = r[5] / 100;   // observed §14a limit as % of grid connection
const grid_conn_kw = r[6] / 100;
const energy_import_wh = r[7] * 65536 + r[8]; // acquired; contract has no field
const grid_limit_kw = Math.round((wmax_lim_pct / 100) * grid_conn_kw * 1000) / 1000;
const reading = {
  ts: new Date().toISOString(),
  grid_kw, pv_kw, load_kw, batt_kw, soc_pct,
  grid_limit_kw, grid_conn_kw, energy_import_wh,
};
global.set('latestReading', reading);
global.set('latestReadingTs', Date.now());
msg.reading = reading;
node.status({ fill: 'green', shape: 'dot', text: 'grid ' + grid_kw.toFixed(1) + 'kW soc ' + soc_pct.toFixed(0) + '%' });
return msg;

// Build the BINDING telemetry payload (docs/contracts/mqtt-telemetry.schema.json)
// and publish on ems/{tenant}/{site}/{device}/telemetry at QoS1.
const r = msg.reading || global.get('latestReading');
if (!r) return null;
const ids = global.get('ids');
const seq = (context.get('seq') || 0) + 1;
context.set('seq', seq);
msg.topic = 'ems/' + ids.tenant + '/' + ids.site + '/' + ids.device + '/telemetry';
msg.qos = 1;
msg.retain = false;
msg.payload = {
  schema_version: '1.0',
  tenant_id: ids.tenant,
  site_id: ids.site,
  device_id: ids.device,
  ts: r.ts,
  seq,
  measurements: {
    power_kw: r.grid_kw,
    soc_pct: r.soc_pct,
    pv_power_kw: r.pv_kw,
    load_kw: r.load_kw,
    grid_limit_kw: r.grid_limit_kw,
  },
};
return msg;

// Lightweight heartbeat on .../status. No frozen schema for status yet, so this
// stays minimal and clearly versioned.
const ids = global.get('ids');
const r = global.get('latestReading');
const schedTs = global.get('scheduleTs') || 0;
const STALE_MS = 20 * 60 * 1000;
const source = schedTs && (Date.now() - schedTs) <= STALE_MS ? 'schedule' : 'default';
msg.topic = 'ems/' + ids.tenant + '/' + ids.site + '/' + ids.device + '/status';
msg.qos = 1;
msg.retain = false;
msg.payload = {
  schema_version: '1.0',
  tenant_id: ids.tenant,
  site_id: ids.site,
  device_id: ids.device,
  ts: new Date().toISOString(),
  online: true,
  control_source: source,
  soc_pct: r ? r.soc_pct : null,
};
return msg;

// Cache the retained cloud schedule. Cloud -> Edge, retained; delivered on
// subscribe. Contract: docs/contracts/mqtt-schedule.schema.json (FROZEN) - the
// flow consumes { schema_version, slot_minutes, slots: [{ start: RFC3339,
// battery_setpoint_kw }] } and ignores the plan metadata fields.
// Subscribed on the wildcard ems/+/+/+/schedule; accept only this device's
// topic so env-overridden VP_TENANT_ID/VP_SITE_ID/VP_DEVICE_ID still match.
const ids = global.get('ids') || {};
const parts = (msg.topic || '').split('/'); // ems/{tenant}/{site}/{device}/schedule
if (parts.length < 5 || parts[1] !== ids.tenant || parts[2] !== ids.site || parts[3] !== ids.device) { return null; }
const s = msg.payload;
if (!s || !Array.isArray(s.slots)) { node.warn('malformed schedule payload'); return null; }
global.set('schedule', s);
global.set('scheduleTs', Date.now());
node.status({ fill: 'green', shape: 'dot', text: s.slots.length + ' slots @' + (s.slot_minutes || 15) + 'min' });
return null;

// Schedule-Exec: each tick pick the 15-min slot covering 'now' and emit its
// setpoint. Only acts while the schedule is FRESH; otherwise the watchdog owns
// control (mutually exclusive on freshness).
const s = global.get('schedule');
const ts = global.get('scheduleTs') || 0;
const STALE_MS = 20 * 60 * 1000;
if (!s || (Date.now() - ts) > STALE_MS) { node.status({ fill: 'grey', shape: 'ring', text: 'stale/none' }); return null; }
const now = Date.now();
const slotMs = (s.slot_minutes || 15) * 60000;
let chosen = null;
for (const slot of s.slots) {
  const start = Date.parse(slot.start);
  if (!isNaN(start) && now >= start && now < start + slotMs) { chosen = slot; break; }
}
if (!chosen) { node.status({ fill: 'yellow', shape: 'ring', text: 'no active slot' }); return null; }
msg.setpoint = { battery_kw: chosen.battery_setpoint_kw, source: 'schedule', slot_start: chosen.start };
node.status({ fill: 'blue', shape: 'dot', text: 'slot ' + chosen.battery_setpoint_kw + 'kW' });
return msg;

// Default-Watchdog: on a missing/stale schedule, fall back to a deliberately
// simple self-consumption default - battery follows (PV - load): charge PV
// surplus, discharge to cover deficit. Guards clamp it. No price/time logic.
const ts = global.get('scheduleTs') || 0;
const STALE_MS = 20 * 60 * 1000;
const fresh = ts && (Date.now() - ts) <= STALE_MS;
if (fresh) { node.status({ fill: 'grey', shape: 'ring', text: 'schedule fresh' }); return null; }
const r = global.get('latestReading');
if (!r) { node.status({ fill: 'yellow', shape: 'ring', text: 'no reading' }); return null; }
const batt_kw = Math.round((r.pv_kw - r.load_kw) * 1000) / 1000;
msg.setpoint = { battery_kw: batt_kw, source: 'default' };
node.status({ fill: 'blue', shape: 'dot', text: 'self-consumption ' + batt_kw.toFixed(1) + 'kW' });
return msg;

// Guards: local plausibility / limit checks before any inverter write.
// Clamp charge/discharge power, enforce SoC bounds, and keep the commanded
// battery power inside the observed §14a released envelope. Then write the
// battery setpoint register (FC6, addr 40) as int16 0.01 kW two's-complement.
const L = global.get('assetLimits');
const r = global.get('latestReading') || {};
const sp = msg.setpoint || {};
let kw = Number(sp.battery_kw);
if (!isFinite(kw)) { node.warn('non-finite setpoint, blocked'); return null; }
// 1) power limits (+charge / -discharge)
kw = Math.max(-L.max_discharge_kw, Math.min(L.max_charge_kw, kw));
// 2) SoC bounds
if (typeof r.soc_pct === 'number') {
  if (r.soc_pct >= L.soc_max_pct && kw > 0) kw = 0;
  if (r.soc_pct <= L.soc_min_pct && kw < 0) kw = 0;
}
// 3) observed §14a envelope: don't let charging push grid import past the limit
if (typeof r.grid_limit_kw === 'number' && typeof r.load_kw === 'number' && typeof r.pv_kw === 'number') {
  const predictedGrid = r.load_kw + kw - r.pv_kw; // + = import
  if (predictedGrid > r.grid_limit_kw) {
    const maxKw = r.grid_limit_kw - r.load_kw + r.pv_kw;
    if (kw > maxKw) kw = maxKw;
  }
}
// 4) re-apply power limits last: the §14a envelope can push kw below
// -max_discharge_kw, so the final value must never escape the rated band.
kw = Math.max(-L.max_discharge_kw, Math.min(L.max_charge_kw, kw));
kw = Math.round(kw * 1000) / 1000;
const raw = Math.round(kw * 100) & 0xffff;
msg.payload = { value: raw, fc: 6, unitid: 1, address: 40, quantity: 1 };
node.status({ fill: 'blue', shape: 'dot', text: (sp.source || '?') + ' -> ' + kw + 'kW' });
return msg;

// One-shot on start: assert EMS control (reg 41 = 1) so the simulated inverter
// obeys setpoint writes.
msg.payload = { value: 1, fc: 6, unitid: 1, address: 41, quantity: 1 };
return msg;
